class Solution {
public:
    string maxSumOfSquares(int num, int sum) {
        if (sum > 9LL * num) {
            return "";
        }

        int k = sum / 9;
        int r = sum % 9;

        string result;
        result.reserve(num);
        result.append(k, '9');
        if (r > 0) {
            result.push_back('0' + r);
        }
        result.append(num - k - (r > 0 ? 1 : 0), '0');

        return result;
    }
};
